public final class VillageDefenseManager extends SavedData { private final Map<UUID,VillageDefense> data=new HashMap<>(); private static final Codec<VillageDefense> C=RecordCodecBuilder.create(i->i.group(Codec.INT.fieldOf("livingGolems").forGetter(VillageDefense::livingGolems),Codec.INT.fieldOf("armedVillagers").forGetter(VillageDefense::armedVillagers),Codec.INT.fieldOf("recentDeaths").forGetter(VillageDefense::recentDeaths)).apply(i,VillageDefense::new)); private static final Codec<VillageDefenseManager> MC=Codec.unboundedMap(Codec.STRING.xmap(UUID::fromString,UUID::toString),C).xmap(m->{var x=new VillageDefenseManager();x.data.putAll(m);return x;},x->x.data); private static final SavedDataType<VillageDefenseManager> TYPE=new SavedDataType<>(Identifier.fromNamespaceAndPath("the_world_remembers","village_defense"),VillageDefenseManager::new,MC,null); public static VillageDefenseManager get(MinecraftServer s){ServerLevel l=s.getLevel(ServerLevel.OVERWORLD);return l==null?new VillageDefenseManager():l.getDataStorage().computeIfAbsent(TYPE);} public void observe(UUID id,VillageDefense d){var old=data.get(id); if(!d.equals(old)){data.put(id,d);setDirty();}} public VillageDefense get(UUID id){return data.get(id);} }
